parameters.text:
=Eres un ingeniero SRE. A partir de esta salida de diagnostico (kubectl) de una ArgoCD Application, redacta un correo de diagnostico en espanol (con asunto y cuerpo), claro y accionable para el equipo. No inventes datos que no esten en la salida.

Aplicacion: {{ $('Webhook').first().json.body.app }}

Salida de kubectl:
{{ $json.stdout }}

parameters.jsCode:
const app = (($('Webhook').first().json.body) || {}).app || 'desconocida';

let diag = {};
try { diag = $('Diagnostico (kubectl)').first().json || {}; } catch (e) { diag = {}; }

let llmText = '';
let llmError = '';
try {
  const out = $('LLM - redactar correo').first().json || {};
  llmText = out.text || out.response || out.output || '';
  if (!llmText && out.error) {
    llmError = typeof out.error === 'string' ? out.error : JSON.stringify(out.error);
  }
} catch (e) { llmError = String(e && e.message ? e.message : e); }

const stdout = String(diag.stdout || '').trim();
const stderr = String(diag.stderr || '').trim();
const exitCode = diag.exitCode;

const fallback = [
  `Aplicacion ArgoCD: ${app}`,
  `kubectl exitCode=${exitCode}`,
  ...(llmError ? [`LLM no disponible: ${llmError}`] : []),
  '',
  '--- salida de kubectl ---',
  stdout || '(sin salida)',
  ...(stderr ? ['', '--- stderr ---', stderr] : []),
].join('\n');

const llmUsed = Boolean(llmText && String(llmText).trim());
if (!llmUsed && !llmError) { llmError = 'el paso LLM no devolvio texto (revisa credenciales/cuota en la ejecucion de n8n)'; }

return [{ json: {
  to: 'sre@lab.test',
  subject: `[kubelab] Diagnostico ArgoCD: ${app}`,
  body: llmUsed ? llmText : fallback,
  llmUsed,
  llmError: llmError || null,
  application: app,
  exitCode: exitCode ?? null,
} }];
